import Foundation
import Testing
@testable import F1LapKit

// MARK: - Fixtures (real sidecar replies, regenerated by scripts/fixtures.py)

private func fixture<T: Decodable>(_ name: String, as: T.Type = T.self) throws -> T {
    let url = try #require(Bundle.module.url(forResource: "Fixtures/\(name)", withExtension: "json"))
    return try SidecarClient.decoder.decode(T.self, from: Data(contentsOf: url))
}

@Suite struct DecodingTests {
    @Test func schedule() throws {
        let events: [Event] = try fixture("schedule")
        let monza = try #require(events.first { $0.location == "Monza" })
        #expect(monza.sessions.contains("Qualifying"))
    }

    @Test func session() throws {
        let info: SessionInfo = try fixture("session")
        #expect(info.drivers.count == 20)
        #expect(info.laps(of: "LEC").contains { $0.valid && $0.personalBest })
    }

    @Test func compare() throws {
        let c: CompareResult = try fixture("compare")
        #expect(c.reference.driver == "LEC" && c.other.driver == "SAI")
        #expect(c.metrics.count == 2)
        #expect(!c.corners.isEmpty && c.corners.allSatisfy { $0.phaseDeltaS.keys.contains("braking") })
        let track = try #require(c.circuit.track)
        #expect(track.x.count == track.y.count && track.x.count > 100)
        #expect(c.traces.columns.allSatisfy { $0.count == c.grid.samples })
    }

    @Test func rate() throws {
        let r: Rating = try fixture("rate")
        #expect(r.driver == "LEC")
        #expect((0...100).contains(r.score))
        #expect(r.theoreticalBestS <= r.lapTimeS)
        let p = try #require(r.perfect)
        #expect(p.error == nil)
        #expect(try #require(p.simLapTimeS) < r.lapTimeS)
        #expect(p.summary?.first?.hasPrefix("LEC L20 was") == true)
        #expect(p.corners?.isEmpty == false && p.traces != nil)
    }

    @Test func lapRefEncodesFastest() throws {
        let fastest = try JSONEncoder().encode(LapRef(driver: "LEC"))
        let lap = try JSONEncoder().encode(LapRef(driver: "LEC", lap: 12))
        #expect(String(decoding: fastest, as: UTF8.self).contains(#""lap":"fastest""#))
        #expect(String(decoding: lap, as: UTF8.self).contains(#""lap":12"#))
    }
}

// MARK: - SoA trace files

@Suite struct SoATests {
    /// f64 column at 0, i16 column at an 8-aligned offset after padding — as `write_soa` lays out.
    private func file(_ bytes: [UInt8]) throws -> URL {
        let url = FileManager.default.temporaryDirectory.appending(path: "\(UUID()).f1soa")
        try Data(bytes).write(to: url)
        return url
    }

    @Test func readsF64AndI16() throws {
        var bytes: [UInt8] = []
        for v in [1.5, -2.25, 300.0] { withUnsafeBytes(of: v.bitPattern.littleEndian) { bytes += $0 } }
        for g in [Int16(3), -1, 8] { withUnsafeBytes(of: g.littleEndian) { bytes += $0 } }
        let url = try file(bytes)
        defer { try? FileManager.default.removeItem(at: url) }
        let t = try Traces.read(url, layout: [
            .init(name: "speed", dtype: "f64", offset: 0, count: 3),
            .init(name: "gear", dtype: "i16", offset: 24, count: 3),
        ])
        #expect(t["speed"] == [1.5, -2.25, 300.0])
        #expect(t["gear"] == [3, -1, 8])
        #expect(t["missing"].isEmpty)
    }

    @Test func rejectsBadLayout() throws {
        let url = try file([UInt8](repeating: 0, count: 16))
        defer { try? FileManager.default.removeItem(at: url) }
        #expect(throws: SoAError.outOfBounds("x")) {
            try Traces.read(url, layout: [.init(name: "x", dtype: "f64", offset: 8, count: 2)])
        }
        #expect(throws: SoAError.outOfBounds("x")) {
            try Traces.read(url, layout: [.init(name: "x", dtype: "f64", offset: 0, count: .max)])
        }
        #expect(throws: SoAError.unsupportedDType("f32")) {
            try Traces.read(url, layout: [.init(name: "x", dtype: "f32", offset: 0, count: 1)])
        }
    }
}

// MARK: - Sidecar transport (fake sidecars, no Python needed)

@Suite struct TransportTests {
    private func shell(_ script: String) -> SidecarClient {
        SidecarClient(config: SidecarConfig(executable: URL(filePath: "/bin/sh"), arguments: ["-c", script]))
    }

    @Test func mapsRpcErrors() async throws {
        let client = shell(#"read l; echo '{"jsonrpc":"2.0","id":1,"error":{"code":-32000,"message":"no lap"}}'; read l"#)
        defer { Task { await client.shutdown() } }
        await #expect(throws: SidecarError.rpc(code: -32000, message: "no lap")) {
            let _: Int = try await client.call("rate", NoParams())
        }
    }

    @Test func failsInFlightRequestsWhenSidecarExits() async throws {
        let client = shell("read l; echo 'boom' >&2; exit 3")
        do {
            let _: Int = try await client.call("compare", NoParams())
            Issue.record("expected the call to fail")
        } catch let SidecarError.exited(_, log) {
            #expect(log.contains("boom") || log.isEmpty)  // stderr may race the stdout close
        }
    }

    @Test func restartsAfterExit() async throws {
        // Each process answers one request with result 7 and exits; the next call must relaunch.
        let client = shell(#"read l; echo '{"jsonrpc":"2.0","id":'$(echo "$l" | sed 's/.*"id":\([0-9]*\).*/\1/')',"result":7}'"#)
        for _ in 0..<2 {
            var value: Int?
            for _ in 0..<20 where value == nil {  // the exit may race the next send: retry
                value = try? await client.call("ping", NoParams())
            }
            #expect(value == 7)
        }
        await client.shutdown()
    }

    @Test func deliversProgressNotifications() async throws {
        let client = shell(#"read l; echo '{"jsonrpc":"2.0","method":"progress","params":{"message":"Reading laps","done":25,"total":900}}'; echo '{"jsonrpc":"2.0","id":1,"result":7}'; read l"#)
        defer { Task { await client.shutdown() } }
        let value: Int = try await client.call("rate", NoParams())
        #expect(value == 7)
        var updates = client.progress.makeAsyncIterator()
        #expect(await updates.next() == SidecarProgress(message: "Reading laps", done: 25, total: 900))
    }

    @Test func launchFailure() async {
        let client = SidecarClient(config: SidecarConfig(
            executable: URL(filePath: "/nonexistent/python"), arguments: []))
        await #expect {
            let _: Int = try await client.call("ping", NoParams())
        } throws: { error in
            if case SidecarError.launchFailed = error { return true }
            return false
        }
    }
}

// MARK: - Live sidecar (repo .venv + cached Monza 2024 Q)

private let repo = ProcessInfo.processInfo.environment["F1LAP_REPO"].map { URL(filePath: $0) }
private let liveAvailable = repo.map {
    FileManager.default.isExecutableFile(atPath: $0.appending(path: ".venv/bin/python").path)
        && FileManager.default.fileExists(atPath: $0.appending(path: "cache").path)
} ?? false

@Suite(.enabled(if: liveAvailable, "needs F1LAP_REPO with .venv and cache/"), .serialized)
struct LiveTests {
    private func service() -> F1LapService {
        var config = SidecarConfig.repository(repo!)
        config.environment["F1LAP_CACHE_DIR"] = repo!.appending(path: "cache").path
        return F1LapService(client: SidecarClient(config: config))
    }

    @Test func pingAndUnknownMethod() async throws {
        let svc = service()
        let ping = try await svc.ping()
        #expect(ping.protocol == 1)
        await #expect(throws: SidecarError.self) {
            let _: Int = try await svc.client.call("nope", NoParams())
        }
        await svc.client.shutdown()
    }

    @Test(.timeLimit(.minutes(2))) func compareLoadsTraces() async throws {
        let svc = service()
        let key = SessionKey(year: 2024, event: "Monza", session: "Q")
        async let pong = svc.ping()  // must answer while the session loads
        let (result, traces) = try await svc.compare(
            key, reference: LapRef(driver: "LEC"), other: LapRef(driver: "SAI"))
        _ = try await pong
        #expect(traces["distance"].count == result.grid.samples)
        #expect(traces["delta"].last.map { abs($0 - result.finalDeltaS) < 1e-9 } == true)
        #expect(traces["ref.speed"].max().map { $0 > 300 } == true)

        // Per-side sessions: the reference session also given explicitly for the compared lap.
        let (again, _) = try await svc.compare(
            reference: (key, LapRef(driver: "LEC")), other: (key, LapRef(driver: "SAI")))
        #expect(again.finalDeltaS == result.finalDeltaS && again.other.year == 2024)

        await #expect {
            _ = try await svc.rate(key, lap: LapRef(driver: "XXX"))
        } throws: { ($0 as? SidecarError)?.isAnalysisError == true }
        await svc.client.shutdown()
    }
}
